 * https://github.com/Semkoo/niko-table-registry
 */
import type { RowData } from "@tanstack/react-table"
import { useDataTable } from "../core/data-table-context"
import {
  TablePagination,
  type TablePaginationProps,
} from "../filters/table-pagination"

type DataTablePaginationProps<TData extends RowData> = Omit<
  TablePaginationProps<TData>,
  "table" | "isLoading"
> & {
  /**
   * Override the loading state from context
   */
  isLoading?: boolean
}

export function DataTablePagination<TData extends RowData>({
  isLoading: externalLoading,
  ...props
}: DataTablePaginationProps<TData>) {
  const { table, isLoading: contextLoading } = useDataTable<TData>()

  // Use external loading if provided, otherwise use context loading
  const isLoading = externalLoading ?? contextLoading

  return <TablePagination table={table} isLoading={isLoading} {...props} />
}

/**
 * @required displayName is required for auto feature detection
 * @see "feature-detection.ts"
 */

DataTablePagination.displayName = "DataTablePagination"

"use client"

/**
 * niko-table — created by Semir N. (Semkoo, https://github.com/Semkoo) with AI assistance.
 *
 * Before reporting anything: please check the changelog first.
 *  - In-repo: ./CHANGELOG.md
 *  - Docs site: https://niko-table.com/changelog
 *
 * Found a bug or have a fix? Open an issue or PR on GitHub so other
 * users (and future LLMs reading this code) benefit:
 * https://github.com/Semkoo/niko-table-registry
 */

import React from "react"
import { Button } from "@/components/niko-table/primitives/button"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/niko-table/primitives/select"
import { Input } from "@/components/ui/input"
import { ChevronLeft, ChevronRight } from "lucide-react"
import { Skeleton } from "@/components/ui/skeleton"

import type { DataTableInstance } from "../types"
import type { RowData } from "@tanstack/react-table"
export interface TablePaginationProps<TData extends RowData> {
  table: DataTableInstance<TData>
  pageSizeOptions?: number[]
  defaultPageSize?: number
  /**
   * External loading state (e.g., from API)
   */
  isLoading?: boolean
  /**
   * External fetching state (e.g., from TanStack Query).
   * Disables nav while a request is in flight so users can't advance the
   * cursor before the next page resolves.
   */
  isFetching?: boolean
  /**
   * Explicitly disable the next page button.
   * Useful when you want to prevent navigation during initial load but allow it during background fetching.
   */
  disableNextPage?: boolean
  /**
   * Explicitly disable the previous page button.
   * Useful when you want to prevent navigation during initial load but allow it during background fetching.
   */
  disablePreviousPage?: boolean
  /**
   * Total count of items from server (for server-side pagination).
   * If provided, this will be used instead of table.getFilteredRowModel().rows.length
   */
  totalCount?: number
  onPageSizeChange?: (pageSize: number, pageIndex: number) => void
  onPageChange?: (pageIndex: number) => void
  onNextPage?: (pageIndex: number) => void
  onPreviousPage?: (pageIndex: number) => void
  /**
   * Callback when pagination initialization is complete
   */
  onPaginationReady?: () => void
}
export function TablePagination<TData extends RowData>({
  table,
  pageSizeOptions = [10, 25, 50, 100],
  defaultPageSize = pageSizeOptions[0] ?? 10,
  isLoading,
  isFetching,
  disableNextPage,
  disablePreviousPage,
  totalCount,
  onPageSizeChange,
  onPageChange,
  onNextPage,
  onPreviousPage,
  onPaginationReady,
}: TablePaginationProps<TData>) {
  const { pageIndex, pageSize } = table.state.pagination

  // Use totalCount if provided (server-side), otherwise use filtered row model (client-side)
  const totalRows = totalCount ?? table.getFilteredRowModel().rows.length
  const startItem = totalRows === 0 ? 0 : pageIndex * pageSize + 1
  const endItem = Math.min((pageIndex + 1) * pageSize, totalRows)
  const totalPages = table.getPageCount()
  const currentPage = pageIndex + 1

  const [pageInput, setPageInput] = React.useState<string | null>(null)
  const displayValue = pageInput ?? currentPage.toString()

  // Disable nav during any in-flight load (initial OR background fetch) so
  // users can't advance the cursor while the next page is still resolving.
  const canNextPage = table.getCanNextPage()
  const isDisabled = isLoading || isFetching
  const canGoNext = !disableNextPage && !isDisabled && canNextPage
  const canGoPrevious =
    !disablePreviousPage && !isDisabled && table.getCanPreviousPage()

  // Set default page size on initial render
  React.useEffect(() => {
    if (pageSize !== defaultPageSize) {
      table.setPageSize(defaultPageSize)
    }
    onPaginationReady?.()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const handlePageSizeChange = React.useCallback(
    // Base UI selects pass null on clear; Radix never does
    (value: string | null) => {
      if (!value) return
      const newPageSize = Number(value)
      const newPageIndex = Math.floor((pageIndex * pageSize) / newPageSize)
      table.setPageSize(newPageSize)
      onPageSizeChange?.(newPageSize, newPageIndex)
    },
    [table, pageIndex, pageSize, onPageSizeChange],
  )

  const handlePageInputChange = React.useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      setPageInput(e.target.value)
    },
    [],
  )

  const handlePageInputBlur = React.useCallback(() => {
    const page = parseInt(pageInput ?? "", 10)
    if (!Number.isNaN(page) && page >= 1 && page <= totalPages) {
      const newPageIndex = page - 1
      table.setPageIndex(newPageIndex)
      onPageChange?.(newPageIndex)
    }
    setPageInput(null)
  }, [pageInput, totalPages, table, onPageChange])

  const handlePageInputKeyDown = React.useCallback(
    (e: React.KeyboardEvent<HTMLInputElement>) => {
      if (e.key === "Enter") {
        e.currentTarget.blur()
      }
    },
    [],
  )

  const handlePreviousPage = React.useCallback(() => {
    const newPageIndex = pageIndex - 1
    table.previousPage()
    onPreviousPage?.(newPageIndex)
  }, [table, pageIndex, onPreviousPage])

  const handleNextPage = React.useCallback(() => {
    const newPageIndex = pageIndex + 1
    table.nextPage()
    onNextPage?.(newPageIndex)
  }, [table, pageIndex, onNextPage])

  // Show loading skeleton while initializing
  if (isLoading) {
    return (
      <div className="flex flex-wrap items-center justify-between gap-4 px-4 py-2">
        <div className="flex items-center space-x-2">
          <Skeleton className="h-8 w-24" />
          <Skeleton className="h-8 w-16" />
        </div>
        <Skeleton className="h-8 w-32" />
        <div className="flex items-center space-x-4">
          <div className="flex items-center space-x-2">
            <Skeleton className="h-8 w-12" />
            <Skeleton className="h-8 w-20" />
          </div>
          <div className="flex items-center space-x-1">
            <Skeleton className="h-8 w-8" />
            <Skeleton className="h-8 w-8" />
          </div>
        </div>
      </div>
    )
  }

  return (
    <nav
      className="flex flex-wrap items-center justify-between gap-x-6 gap-y-2 px-4 py-2"
      aria-label="Table pagination"
    >
      <div className="flex items-center space-x-2">
        <span
          className="text-sm whitespace-nowrap text-muted-foreground"
          id="pagination-page-size-label"
        >
          Items per page
        </span>
        <Select
          value={`${Number(pageSize) === 0 ? defaultPageSize : Number(pageSize)}`}
          onValueChange={handlePageSizeChange}
          disabled={isLoading}
        >
          <SelectTrigger
            size="sm"
            className="w-16 focus:ring-0"
            aria-label="Select page size"
            aria-labelledby="pagination-page-size-label"
          >
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {pageSizeOptions?.map(size => (
              <SelectItem key={size} value={`${size}`}>
                {size}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <div
        className="flex-1 text-right text-sm whitespace-nowrap text-muted-foreground md:text-center"
        role="status"
        aria-live="polite"
        aria-atomic="true"
      >
        {totalRows === 0
          ? "0 items"
          : `${startItem}-${endItem} of ${totalRows} items`}
      </div>

      <div className="ml-auto flex items-center space-x-4">
        <div className="flex items-center space-x-2 text-sm text-muted-foreground">
          <label htmlFor="page-number-input" className="sr-only">
            Page number
          </label>
          <Input
            id="page-number-input"
            type="number"
            min="1"
            max={totalPages}
            value={displayValue}
            onChange={handlePageInputChange}
            onBlur={handlePageInputBlur}
            onKeyDown={handlePageInputKeyDown}
            className="h-8 min-w-12 text-center"
            style={{
              width: `${Math.max(String(totalPages).length, 2) + 1}ch`,
            }}
            disabled={totalPages === 0 || isLoading || isFetching}
            aria-label={`Page ${currentPage} of ${totalPages}`}
          />
          <span className="whitespace-nowrap" aria-hidden="true">
            of {Math.max(1, totalPages)} pages
          </span>
        </div>

        <div className="flex items-center space-x-1">
          <Button
            variant="ghost"
            size="sm"
            className="h-8 w-8 p-0"
            onClick={handlePreviousPage}
            disabled={!canGoPrevious}
            aria-label={`Go to previous page, page ${pageIndex}`}
            title="Go to previous page"
          >
            <ChevronLeft className="h-4 w-4" aria-hidden="true" />
          </Button>
          <Button
            variant="ghost"
            size="sm"
            className="h-8 w-8 p-0"
            onClick={handleNextPage}
            disabled={!canGoNext}
            aria-label={`Go to next page, page ${pageIndex + 2}`}
            title="Go to next page"
          >
            <ChevronRight className="h-4 w-4" aria-hidden="true" />
          </Button>
        </div>
      </div>
    </nav>
  )
}

/**
 * @required displayName is required for auto feature detection
 * @see "feature-detection.ts"
 */

TablePagination.displayName = "TablePagination"

"use client"

/**
 * Niko Table's button primitive, React Aria build: shadcn's React Aria
 * `Button` behind the Radix `Button` API Niko Table calls it with (native
 * `<button>` props, `variant`, `size`, `asChild`).
 *
 * - `onClick` goes to React Aria's `onClick`, its alias of `onPress`: a real
 *   MouseEvent on click and a synthesized click for keyboard and screen-reader
 *   presses, so `stopPropagation()` / `shiftKey` keep working.
 * - `disabled` becomes `isDisabled`.
 * - Everything else (title, tabIndex, role, aria-*, key and mouse handlers) goes
 *   on the `<button>` through React Aria's `render`, as on a native button.
 *   React Aria's Button would drop those attributes and stop key events.
 *
 * Overlay triggers (`PopoverTrigger asChild` and the rest) hand their press to
 * this button, so an `asChild` trigger's child must be this Button (or
 * shadcn's), as with shadcn's own React Aria triggers.
 */
import * as React from "react"
import { mergeProps } from "react-aria"
import type { VariantProps } from "class-variance-authority"

import {
  Button as ButtonPrimitive,
  buttonVariants,
} from "@/components/ui/button"
import { cn } from "@/lib/utils"

type OnPressClick = React.ComponentProps<typeof ButtonPrimitive>["onClick"]

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  if (
    asChild &&
    React.isValidElement<React.HTMLAttributes<HTMLElement>>(children)
  ) {
    // Slot: the child element is the button (e.g. a link styled as one); its
    // own handlers and refs compose with the button's.
    return React.cloneElement(children, {
      ...mergeProps(children.props, { "data-slot": "button" }, props),
      className: cn(
        buttonVariants({ variant, size }),
        className,
        children.props.className,
      ),
    } as React.HTMLAttributes<HTMLElement>)
  }

  const { ref, id, type, slot, disabled, onClick, onMouseDown, ...native } =
    props
  return (
    <ButtonPrimitive
      ref={ref}
      id={id}
      type={type}
      slot={slot}
      variant={variant}
      size={size}
      className={className}
      isDisabled={disabled}
      onClick={onClick as OnPressClick}
      render={domProps => (
        <button
          {...mergeProps(domProps, native)}
          onMouseDown={event => {
            // React Aria's press handler stops every left mousedown; a native
            // button lets it bubble (the grid selects cells on mousedown).
            event.stopPropagation = () => {}
            domProps.onMouseDown?.(event)
            delete (event as Partial<typeof event>).stopPropagation
            onMouseDown?.(event)
          }}
        />
      )}
    >
      {children}
    </ButtonPrimitive>
  )
}

export { Button, buttonVariants }

"use client"

/**
 * Niko Table's select primitive, React Aria build. Radix-shaped API
 * (`Select value onValueChange open onOpenChange disabled`, `SelectTrigger`,
 * `SelectValue placeholder`, `SelectContent`, `SelectItem value`) on top of the
 * React Aria shadcn select (a React Aria `Select` with a `ListBox`).
 */
import * as React from "react"

import {
  Select as SelectRoot,
  SelectContent as SelectPopover,
  SelectItem as SelectOption,
  SelectTrigger as SelectButton,
  SelectValue as SelectValuePrimitive,
} from "@/components/ui/select"

/** Plain text of a node tree, for React Aria's type-to-select. */
function textOf(node: React.ReactNode): string {
  if (typeof node === "string" || typeof node === "number") return String(node)
  if (Array.isArray(node)) return node.map(textOf).join("")
  if (React.isValidElement<{ children?: React.ReactNode }>(node))
    return textOf(node.props.children)
  return ""
}

function Select({
  value,
  defaultValue,
  onValueChange,
  open,
  onOpenChange,
  disabled,
  required,
  name,
  children,
}: {
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  open?: boolean
  onOpenChange?: (open: boolean) => void
  disabled?: boolean
  required?: boolean
  name?: string
  children?: React.ReactNode
}) {
  // React Aria labels the select on its root; Radix call sites label the
  // trigger, so lift the trigger's aria-label / aria-labelledby. Only a
  // direct-child SelectTrigger is found; a wrapped one leaves it unlabelled.
  const trigger = React.Children.toArray(children).find(
    (child): child is React.ReactElement<SelectTriggerProps> =>
      React.isValidElement(child) && child.type === SelectTrigger,
  )
  return (
    <SelectRoot
      aria-label={trigger?.props["aria-label"]}
      aria-labelledby={trigger?.props["aria-labelledby"]}
      value={value}
      defaultValue={defaultValue}
      onChange={key => {
        if (key !== null) onValueChange?.(String(key))
      }}
      isOpen={open}
      onOpenChange={onOpenChange}
      isDisabled={disabled}
      isRequired={required}
      name={name}
    >
      {children}
    </SelectRoot>
  )
}

interface SelectTriggerProps {
  className?: string
  size?: "sm" | "default"
  id?: string
  title?: string
  children?: React.ReactNode
  /** Read by `Select`, which labels the React Aria select with it. */
  "aria-label"?: string
  /** Read by `Select`, which labels the React Aria select with it. */
  "aria-labelledby"?: string
  /** Radix wiring; React Aria links the trigger to its list itself. */
  "aria-controls"?: string
}

function SelectTrigger({
  className,
  size,
  id,
  title,
  children,
}: SelectTriggerProps) {
  return (
    <SelectButton className={className} size={size} id={id}>
      {/* React Aria's button takes no `title`; keep the hint on its content. */}
      <span title={title} className="contents">
        {children}
      </span>
    </SelectButton>
  )
}

function SelectValue({
  placeholder,
  className,
}: {
  placeholder?: React.ReactNode
  className?: string
}) {
  return (
    <SelectValuePrimitive className={className}>
      {({ isPlaceholder, defaultChildren }) =>
        isPlaceholder ? placeholder : defaultChildren
      }
    </SelectValuePrimitive>
  )
}

function SelectContent({
  className,
  children,
}: {
  className?: string
  children?: React.ReactNode
  /** Radix wiring; React Aria links the trigger to its list itself. */
  id?: string
  /** Radix option; ignored, React Aria always positions as a popover. */
  position?: "popper" | "item-aligned"
}) {
  return <SelectPopover className={className}>{children}</SelectPopover>
}

function SelectItem({
  value,
  disabled,
  className,
  children,
}: {
  value: string
  disabled?: boolean
  className?: string
  children?: React.ReactNode
}) {
  return (
    <SelectOption
      id={value}
      isDisabled={disabled}
      className={className}
      textValue={textOf(children) || value}
    >
      {children}
    </SelectOption>
  )
}

export { Select, SelectContent, SelectItem, SelectTrigger, SelectValue }
